begin;
do $test$
declare
 o constant uuid:='00000000-0000-4000-8000-000000000010';
 q constant uuid:='00000000-0000-4000-8000-000000000011';
 x constant uuid:='00000000-0000-4000-8000-000000000012';
 a constant uuid:='62020000-0000-4000-8000-000000000001';
 declined_id uuid;withdrawn_id uuid;accepted_id uuid;chat_id uuid;before_chat jsonb;before_rows jsonb;r jsonb;first_result jsonb;denied boolean;action text;
begin
 insert into public.apartments(id,lister_id,source,title,address,lat,lng,price,bedrooms)values(a,o,'user','Transition fixture','No real address',31.25,34.79,1800,1);
 insert into public.apartment_rooms(apartment_id,monthly_price,available_from,is_available)values(a,1800,'2026-12-01',true);
 perform set_config('request.jwt.claim.sub',q::text,true);execute'set local role authenticated';declined_id:=public.create_listing_inquiry(a,'Owner decline intro');execute'reset role';
 perform set_config('request.jwt.claim.sub',x::text,true);execute'set local role authenticated';withdrawn_id:=public.create_listing_inquiry(a,'Requester withdraw intro');execute'reset role';
 insert into public.listing_inquiries(apartment_id,requester_id)values(a,'00000000-0000-4000-8000-000000000013')returning id into accepted_id;
 select jsonb_build_array((select count(*)from public.conversations),(select count(*)from public.messages),(select count(*)from public.groups))into before_chat;
 perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000014',true);execute'set local role authenticated';
 foreach action in array array['decline','withdraw','reconfirm']loop denied:=false;begin perform public.transition_listing_inquiry(declined_id,action);exception when others then if sqlerrm<>'NOT_FOUND'then raise;end if;denied:=true;end;if not denied then raise exception'Outside actor transition';end if;end loop;
 execute'reset role';
 perform set_config('request.jwt.claim.sub',q::text,true);execute'set local role authenticated';
 denied:=false;begin perform public.transition_listing_inquiry(declined_id,'decline');exception when others then if sqlerrm<>'NOT_FOUND'then raise;end if;denied:=true;end;if not denied then raise exception'Requester declined as owner';end if;
 denied:=false;begin perform public.transition_listing_inquiry(withdrawn_id,'withdraw');exception when others then if sqlerrm<>'NOT_FOUND'then raise;end if;denied:=true;end;if not denied then raise exception'Foreign requester withdrawal';end if;
 execute'reset role';perform set_config('request.jwt.claim.sub',o::text,true);execute'set local role authenticated';
 denied:=false;begin perform public.transition_listing_inquiry(declined_id,'accept');exception when others then if sqlerrm<>'VALIDATION_FAILED'then raise;end if;denied:=true;end;if not denied then raise exception'Invalid action accepted';end if;
 denied:=false;begin perform public.transition_listing_inquiry('62020000-0000-4000-8000-000000000099','decline');exception when others then if sqlerrm<>'NOT_FOUND'then raise;end if;denied:=true;end;if not denied then raise exception'Unknown transition target';end if;
 denied:=false;begin perform public.transition_listing_inquiry(declined_id,'withdraw');exception when others then if sqlerrm<>'NOT_FOUND'then raise;end if;denied:=true;end;if not denied then raise exception'Owner withdrew as requester';end if;
 perform public.set_owned_listing_intake(a,false);perform public.set_owned_listing_intake(a,true);
 execute'reset role';perform set_config('request.jwt.claim.sub',q::text,true);execute'set local role authenticated';
 first_result:=public.transition_listing_inquiry(declined_id,'reconfirm');r:=public.transition_listing_inquiry(declined_id,'reconfirm');if r<>first_result or r->>'status'<>'pending'then raise exception'Reconfirm retry failed';end if;
 execute'reset role';if not exists(select 1 from public.listing_inquiries where id=declined_id and reconfirmation_required_at is null and intro='Owner decline intro')then raise exception'Reconfirm changed intro/identity';end if;
 perform set_config('request.jwt.claim.sub',o::text,true);execute'set local role authenticated';
 perform public.set_owned_listing_intake(a,false);
 execute'reset role';perform set_config('request.jwt.claim.sub',x::text,true);execute'set local role authenticated';
 denied:=false;begin perform public.transition_listing_inquiry(withdrawn_id,'reconfirm');exception when others then if sqlerrm<>'STATE_UNAVAILABLE'then raise;end if;denied:=true;end;if not denied then raise exception'Reconfirmed closed intake';end if;
 first_result:=public.transition_listing_inquiry(withdrawn_id,'withdraw');r:=public.transition_listing_inquiry(withdrawn_id,'withdraw');if r<>first_result or r->>'status'<>'withdrawn'then raise exception'Withdraw retry failed';end if;
 execute'reset role';perform set_config('request.jwt.claim.sub',o::text,true);execute'set local role authenticated';
 first_result:=public.transition_listing_inquiry(declined_id,'decline');r:=public.transition_listing_inquiry(declined_id,'decline');if r<>first_result or r->>'status'<>'declined'then raise exception'Decline retry failed';end if;
 if public.list_owner_listing_inquiries(a,'withdrawn')->'items'->0->>'id'<>withdrawn_id::text then raise exception'Withdrawn reader state absent';end if;
 execute'reset role';
 if before_chat<>jsonb_build_array((select count(*)from public.conversations),(select count(*)from public.messages),(select count(*)from public.groups))then raise exception'Terminal transition created chat/message/group';end if;
 if not exists(select 1 from public.listing_inquiries where id=withdrawn_id and intro='Requester withdraw intro'and conversation_id is null)then raise exception'Withdraw lost original intro';end if;
 -- Reopen intake only; terminal requests cannot be reconfirmed or accepted.
 perform set_config('request.jwt.claim.sub',o::text,true);execute'set local role authenticated';perform public.set_owned_listing_intake(a,true);execute'reset role';
 perform set_config('request.jwt.claim.sub',x::text,true);execute'set local role authenticated';
 if public.create_listing_inquiry(a,'Requester withdraw intro')<>withdrawn_id then raise exception'Terminal legacy retry identity changed';end if;
 execute'reset role';perform set_config('request.jwt.claim.sub',o::text,true);execute'set local role authenticated';perform public.set_owned_room_availability((select id from public.apartment_rooms where apartment_id=a),false);
 execute'reset role';perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000013',true);execute'set local role authenticated';
 denied:=false;begin perform public.transition_listing_inquiry(accepted_id,'reconfirm');exception when others then if sqlerrm<>'STATE_UNAVAILABLE'then raise;end if;denied:=true;end;if not denied then raise exception'Reconfirmed zero inventory';end if;
 execute'reset role';perform set_config('request.jwt.claim.sub',o::text,true);execute'set local role authenticated';perform public.set_owned_room_availability((select id from public.apartment_rooms where apartment_id=a),true);
 execute'reset role';perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000013',true);execute'set local role authenticated';
 insert into public.blocks(blocker_id,blocked_id)values('00000000-0000-4000-8000-000000000013',o);
 denied:=false;begin perform public.transition_listing_inquiry(accepted_id,'reconfirm');exception when others then if sqlerrm<>'STATE_UNAVAILABLE'then raise;end if;denied:=true;end;if not denied then raise exception'Reconfirmed blocked pair';end if;
 delete from public.blocks where blocker_id='00000000-0000-4000-8000-000000000013'and blocked_id=o;
 perform public.transition_listing_inquiry(accepted_id,'reconfirm');
 execute'reset role';perform set_config('request.jwt.claim.sub',o::text,true);execute'set local role authenticated';chat_id:=public.accept_listing_inquiry(accepted_id);execute'reset role';
 select jsonb_agg(to_jsonb(i)order by id)into before_rows from public.listing_inquiries i where apartment_id=a;
 select jsonb_build_object('members',(select jsonb_agg(to_jsonb(m)order by user_id)from public.conversation_members m where conversation_id=chat_id),'messages',(select jsonb_agg(to_jsonb(m)order by id)from public.messages m where conversation_id=chat_id))into before_chat;
 perform set_config('request.jwt.claim.sub',o::text,true);execute'set local role authenticated';
 denied:=false;begin perform public.transition_listing_inquiry(accepted_id,'decline');exception when others then if sqlerrm<>'STATE_UNAVAILABLE'then raise;end if;denied:=true;end;if not denied then raise exception'Accepted inquiry declined';end if;
 execute'reset role';perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000013',true);execute'set local role authenticated';
 foreach action in array array['withdraw','reconfirm']loop denied:=false;begin perform public.transition_listing_inquiry(accepted_id,action);exception when others then if sqlerrm<>'STATE_UNAVAILABLE'then raise;end if;denied:=true;end;if not denied then raise exception'Accepted inquiry mutated';end if;end loop;
 execute'reset role';perform set_config('request.jwt.claim.sub',x::text,true);execute'set local role authenticated';
 denied:=false;begin perform public.transition_listing_inquiry(withdrawn_id,'reconfirm');exception when others then if sqlerrm<>'STATE_UNAVAILABLE'then raise;end if;denied:=true;end;if not denied then raise exception'Terminal inquiry revived';end if;
 execute'reset role';
 if before_rows is distinct from(select jsonb_agg(to_jsonb(i)order by id)from public.listing_inquiries i where apartment_id=a)
 or before_chat is distinct from(select jsonb_build_object('members',(select jsonb_agg(to_jsonb(m)order by user_id)from public.conversation_members m where conversation_id=chat_id),'messages',(select jsonb_agg(to_jsonb(m)order by id)from public.messages m where conversation_id=chat_id)))then raise exception'Refused transition changed accepted history';end if;
 perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000013',true);execute'set local role authenticated';
 if not exists(select 1 from public.listing_address_access where apartment_id=a)then raise exception'Accepted grant was revoked';end if;
 execute'reset role';perform set_config('request.jwt.claim.sub',q::text,true);execute'set local role authenticated';if exists(select 1 from public.listing_address_access where apartment_id=a)then raise exception'Decline granted address';end if;
 execute'reset role';perform set_config('request.jwt.claim.sub',x::text,true);execute'set local role authenticated';if exists(select 1 from public.listing_address_access where apartment_id=a)then raise exception'Withdrawal granted address';end if;
 execute'reset role';
 execute'set local role anon';denied:=false;begin perform public.transition_listing_inquiry(declined_id,'decline');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Anon transition execute';end if;execute'reset role';
 perform set_config('request.jwt.claim.sub','',true);execute'set local role authenticated';denied:=false;begin perform public.transition_listing_inquiry(declined_id,'decline');exception when others then if sqlerrm<>'AUTH_REQUIRED'then raise;end if;denied:=true;end;if not denied then raise exception'Null session transition';end if;execute'reset role';
end;
$test$;
rollback;
